*{box-sizing:border-box} :root{--ink:#17221b;--muted:#758078;--line:#dce1d8;--paper:#f3f4ee;--green:#486c4f;--lime:#b6cb72;--red:#b64337} html,body{margin:0;min-height:100%;background:#eef0e9;color:var(--ink);font-family:'DM Sans',sans-serif}body{padding:0 28px}.game-shell{max-width:1512px;margin:0 auto}.topbar{height:64px;border-bottom:1px solid #dfe3da;display:flex;align-items:center;justify-content:space-between}.wordmark{font-size:13px;font-weight:800;letter-spacing:.16em;color:#202b23;text-decoration:none}.brand-mark{font-size:20px;vertical-align:-2px;color:#718b53;margin-right:8px}.top-center,.sound-button{font:500 10px 'DM Mono',monospace;letter-spacing:.12em;color:#7a837b}.season-dot{display:inline-block;width:7px;height:7px;background:#a2b666;border-radius:50%;margin-right:8px;box-shadow:0 0 0 3px #e1e9d2}.top-divider{padding:0 10px;color:#c5cbc1}.sound-button{border:1px solid #d8ddd3;border-radius:4px;padding:8px 11px;background:transparent;cursor:pointer}.sound-button span{font-size:9px;margin-left:4px}.game-layout{display:grid;grid-template-columns:220px minmax(500px,1fr) 220px;gap:24px;padding-top:25px;align-items:start}.side-panel{padding-top:14px}.eyebrow{font:500 9px 'DM Mono',monospace;color:#71816e;letter-spacing:.18em}.left-panel h1{font:700 29px/1.08 'Playfair Display',serif;letter-spacing:-.03em;margin:12px 0}.left-panel h1 em,.modal-card h2 em,.end-card h2 em{font-weight:600;color:#718553}.intro{font-size:12px;line-height:1.75;color:#778078;margin:12px 0 22px}.quest-card{background:#e6e9df;border:1px solid #dce1d6;border-radius:5px;padding:15px 15px 13px}.quest-top{display:flex;align-items:center;font:500 8px 'DM Mono',monospace;letter-spacing:.12em;color:#778173}.quest-icon{font-size:16px;color:#778c59;margin-right:8px}.quest-rank{margin-left:auto;color:#a38048}.quest-card h2{font:700 21px/1.1 'Playfair Display',serif;margin:11px 0 12px;color:#27342a}.quest-rule{height:1px;background:#cfd6c9;margin-bottom:12px}.quest-row{display:flex;justify-content:space-between;align-items:center;margin:8px 0;font-size:9px}.quest-row span,.reward>span:first-child{font:500 8px 'DM Mono',monospace;letter-spacing:.1em;color:#839083}.quest-row b{font-size:9px;color:#455148;font-weight:600}.reward{margin-top:13px;background:#dce3d3;padding:10px;border-radius:3px;display:flex;align-items:center;gap:5px}.reward strong{font:600 19px 'Playfair Display',serif;margin-left:auto;color:#667e4b}.reward small{font:500 10px 'DM Mono',monospace}.reward-gem{color:#92a36a;font-size:10px}.field-note{display:flex;gap:10px;margin-top:18px;color:#7a8379;font-size:10px;line-height:1.5}.field-note p{margin:0}.field-note strong{color:#55634f;font-size:10px}.note-icon{font-size:21px;color:#9da981}.stage-column{min-width:0}.stage-frame{background:#202b22;border-radius:6px;overflow:hidden;box-shadow:0 12px 28px #2635281c}.stage-topline{height:47px;background:#202b22;display:flex;justify-content:space-between;align-items:center;padding:0 18px;color:#dde2d8}.location{display:flex;align-items:center;gap:10px}.location-icon{font-size:18px;color:#b9ca82}.location b{display:block;font:500 9px 'DM Mono',monospace;letter-spacing:.13em}.location small{font:400 8px 'DM Mono',monospace;letter-spacing:.08em;color:#8f9b8e;display:block;margin-top:3px}.hunt-clock{font:500 11px 'DM Mono',monospace;color:#cdd4c7;letter-spacing:.1em}.clock-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#b4c66c;margin-right:7px;box-shadow:0 0 7px #b4c66c}.canvas-wrap{position:relative;background:#354d3a;overflow:hidden}.canvas-wrap canvas#gameCanvas{display:block;width:100%;height:auto;aspect-ratio:960/600;cursor:crosshair}.boss-bar-wrap{position:absolute;top:17px;left:50%;transform:translateX(-50%);width:48%;max-width:440px;pointer-events:none}.boss-label{display:flex;align-items:center;color:#f3eee1;font:500 9px 'DM Mono',monospace;letter-spacing:.15em;margin-bottom:6px;text-shadow:0 1px 3px #000}.boss-skull{font-size:13px;color:#d4a36a;margin-right:7px}.boss-label small{font-size:7px;letter-spacing:.08em;color:#d3d5c9;margin-left:9px}.boss-phase{margin-left:auto;font-size:7px;color:#e5ba79!important;border:1px solid #e5ba7955;padding:3px 6px;border-radius:2px}.boss-track{height:7px;background:#151c19bd;border:1px solid #d8d8c640;position:relative;padding:1px;border-radius:2px;overflow:hidden}.boss-fill{height:100%;width:100%;background:linear-gradient(90deg,#a94c37,#d27b49);transition:width .25s;border-radius:1px}.boss-segment{position:absolute;height:100%;width:1px;background:#eee7ce8c;top:0;left:33.33%}.boss-segment+.boss-segment{left:66.66%}.center-message{position:absolute;left:50%;top:48%;transform:translate(-50%,-50%);color:white;text-align:center;font:700 26px 'Playfair Display',serif;letter-spacing:.02em;text-shadow:0 2px 8px #000;pointer-events:none;opacity:0;transition:opacity .2s}.center-message.visible{opacity:1}.control-tip{position:absolute;bottom:12px;left:50%;transform:translateX(-50%);white-space:nowrap;border:1px solid #e7e4c04f;background:#17231b9c;border-radius:3px;padding:7px 12px;color:#ccd4c5;font:500 8px 'DM Mono',monospace;letter-spacing:.1em;pointer-events:none}.control-tip span{color:#e1dbb5}.control-tip i{color:#82907c;padding:0 6px;font-style:normal}.pause-button{position:absolute;right:13px;top:13px;width:27px;height:27px;background:#16221caa;color:#e7e9dc;border:1px solid #d5dacd57;border-radius:3px;font-size:12px;cursor:pointer}.stage-bottomline{height:72px;background:#202b22;color:#e2e7dc;display:flex;align-items:center;padding:0 17px;gap:15px}.hunter-status{display:flex;align-items:center;gap:10px;min-width:0;flex:1}.hunter-avatar{width:37px;height:37px;border:1px solid #829271;border-radius:50%;display:grid;place-items:center;color:#d0d5c3;font-size:21px;background:radial-gradient(circle,#455644,#253328)}.hunter-bars{min-width:100px;flex:1;max-width:220px}.hunter-name{font:500 8px 'DM Mono',monospace;letter-spacing:.12em;margin-bottom:5px;white-space:nowrap}.hunter-name span{color:#94a08b;font-size:7px;margin-left:5px}.health-track,.stamina-track{height:8px;background:#111a15;border-radius:1px;position:relative;overflow:hidden}.health-fill{height:100%;width:100%;background:linear-gradient(90deg,#779b5a,#9fbd6a);transition:width .2s}.health-track span{position:absolute;right:5px;top:-1px;color:#f0f3e8;font:400 6px 'DM Mono',monospace;text-shadow:0 1px 2px #111}.stamina-track{height:3px;margin-top:4px}.stamina-fill{height:100%;width:100%;background:#d2b667;transition:width .1s}.consumables{display:flex;align-items:center;gap:7px;border-left:1px solid #455047;padding-left:12px}.consumable{position:relative;width:28px;height:28px;border:1px solid #78846f;background:#344236;border-radius:4px;display:grid;place-items:center;color:#c2d27e}.potion-icon{font-size:16px}.consumable-count{position:absolute;bottom:-4px;right:-4px;background:#b9c780;color:#1b281d;border-radius:8px;min-width:13px;text-align:center;font:500 8px 'DM Mono',monospace}.consumable small{position:absolute;top:-7px;left:1px;font:500 7px 'DM Mono',monospace;color:#c0c9b9}.consumable-label{font:500 7px 'DM Mono',monospace;letter-spacing:.08em;color:#9ca696;line-height:1.4}.weapon-chip{display:flex;align-items:center;gap:8px;border-left:1px solid #455047;padding-left:13px}.weapon-icon{font-size:18px;color:#c2cba8}.weapon-chip b{display:block;font:500 7px 'DM Mono',monospace;letter-spacing:.07em;white-space:nowrap}.weapon-chip small{display:block;font:400 7px 'DM Mono',monospace;color:#9ca696;margin-top:3px}.weapon-chevron{color:#839080;margin-left:2px}.progress-row{display:flex;gap:10px;align-items:center;margin:12px 4px 0;font:500 8px 'DM Mono',monospace;letter-spacing:.1em;color:#7e887d}.progress-track{height:3px;background:#d9ded5;flex:1;max-width:180px}.progress-track i{height:100%;display:block;background:#819761;width:0;transition:width .3s}.progress-row #progressPercent{color:#536b4b}.progress-divider{color:#c9cec5}.faint{color:#a7afa5;font-size:7px}.right-panel{padding-top:14px}.map-heading{display:flex;justify-content:space-between;align-items:center;font:500 9px 'DM Mono',monospace;letter-spacing:.14em;color:#59665a}.map-live{font-size:7px;color:#87917d}.map-live i{display:inline-block;width:5px;height:5px;border-radius:50%;background:#8da668;margin-right:4px}.map-box{height:180px;max-width:180px;margin:10px auto 0;background:#e4e9dc;border:1px solid #d3dbcf;border-radius:3px;position:relative;overflow:hidden}.map-box canvas{width:100%;height:100%;display:block}.map-north{position:absolute;right:7px;top:6px;font:500 8px 'DM Mono',monospace;color:#6d786c}.map-legend{display:flex;justify-content:center;gap:18px;margin:9px 0 21px;font:500 7px 'DM Mono',monospace;color:#818a80;letter-spacing:.08em}.legend-player,.legend-beast{display:inline-block;width:6px;height:6px;border-radius:50%;margin-right:5px}.legend-player{background:#6e8d55}.legend-beast{background:#c45642}.intel-card,.controls-card{border-top:1px solid #d9ded5;padding-top:13px;margin-top:12px}.intel-title{font:500 8px 'DM Mono',monospace;color:#667262;letter-spacing:.13em;margin-bottom:11px}.intel-title span{font-size:15px;color:#849469;vertical-align:-2px;margin-right:6px}.intel-line{display:flex;justify-content:space-between;margin:9px 0;font-size:9px}.intel-line span{font:500 7px 'DM Mono',monospace;letter-spacing:.08em;color:#969f94}.intel-line b{font-size:9px;font-weight:600;color:#52644f}.intel-line b.threat{color:#b24c3e;font:500 8px 'DM Mono',monospace;letter-spacing:.06em}.controls-card{margin-top:19px}.control-row{display:flex;align-items:center;gap:3px;margin:8px 0;color:#7f887f}.control-row kbd{font:500 7px 'DM Mono',monospace;padding:3px 4px;border:1px solid #d5dbd1;border-radius:2px;background:#e8ebe4;min-width:17px;text-align:center;color:#59665b}.control-row span{font:500 7px 'DM Mono',monospace;letter-spacing:.04em;margin-left:7px}.tip-card{display:flex;gap:9px;background:#e5e9df;border-radius:3px;padding:10px;margin-top:17px;color:#83906e}.tip-card>span{font-size:13px}.tip-card p{margin:0;font-size:9px;line-height:1.5;color:#788176}.tip-card b{color:#a34c3d}.footer{height:48px;display:flex;align-items:center;justify-content:space-between;color:#a2aaa0;font:500 7px 'DM Mono',monospace;letter-spacing:.13em}.footer i{font-style:normal;color:#c0c7ba;padding:0 4px}.modal-backdrop{position:fixed;inset:0;background:#121b16bd;backdrop-filter:blur(4px);z-index:5;display:grid;place-items:center;padding:20px;transition:opacity .25s}.modal-backdrop.hidden{display:none}.modal-card{width:min(440px,100%);background:#f1f2eb;border:1px solid #d3dbce;border-radius:5px;padding:35px 40px 29px;box-shadow:0 24px 80px #1017106b;text-align:center;position:relative}.intro-modal:before{content:'';position:absolute;inset:8px;border:1px solid #dfe4d8;pointer-events:none}.modal-emblem{font-size:24px;color:#879a62;margin-bottom:12px}.modal-card h2{font:700 38px/1.05 'Playfair Display',serif;margin:11px 0 12px;letter-spacing:-.03em}.modal-card p{font-size:12px;line-height:1.7;color:#788176;max-width:300px;margin:0 auto 20px}.modal-controls{display:flex;justify-content:center;gap:22px;margin:20px auto 24px}.modal-controls div{display:grid;gap:7px}.modal-controls kbd{font:500 8px 'DM Mono',monospace;letter-spacing:.07em;color:#66715f;background:#e6e9df;border:1px solid #d7ded1;padding:6px 8px}.modal-controls small{font:500 7px 'DM Mono',monospace;color:#8d978b;letter-spacing:.1em}.primary-button{background:#486c4f;color:#f4f4e9;border:0;border-radius:3px;padding:13px 18px;width:100%;font:600 9px 'DM Mono',monospace;letter-spacing:.14em;cursor:pointer;transition:background .2s,transform .2s;position:relative;z-index:1}.primary-button:hover{background:#36563e;transform:translateY(-1px)}.primary-button span{font-size:15px;margin-left:12px;vertical-align:-1px}.modal-foot{font:500 7px 'DM Mono',monospace;letter-spacing:.12em;color:#a2aaa0;margin-top:16px}.result-stats{display:flex;justify-content:center;gap:34px;margin:22px 0 26px}.result-stats div{display:grid;gap:7px}.result-stats small{font:500 7px 'DM Mono',monospace;letter-spacing:.1em;color:#929b90}.result-stats b{font:600 15px 'Playfair Display',serif;color:#50664d}.mobile-actions{display:none}
@media(max-width:1100px){body{padding:0 18px}.game-layout{grid-template-columns:190px minmax(440px,1fr) 185px;gap:15px}.left-panel h1{font-size:26px}.side-panel{padding-top:10px}.quest-card{padding:12px}.map-box{height:165px;max-width:165px}.weapon-chip{padding-left:9px}.stage-bottomline{gap:9px;padding:0 12px}.weapon-chip b{font-size:6px}}
@media(max-width:850px){body{padding:0 12px}.game-layout{grid-template-columns:minmax(0,1fr);gap:13px;padding-top:12px}.stage-column{grid-row:1}.left-panel,.right-panel{display:none}.topbar{height:52px}.top-center{font-size:8px}.footer{height:38px}.boss-bar-wrap{width:55%}.stage-bottomline{height:64px}.mobile-actions{position:fixed;display:flex;right:12px;bottom:14px;gap:9px;z-index:3}.mobile-actions button{width:56px;height:56px;border-radius:50%;border:1px solid #d2d7ca;background:#25342aeb;color:#eceddf;font-size:18px;display:grid;place-content:center;box-shadow:0 4px 12px #17231a48}.mobile-actions small{font:500 6px 'DM Mono',monospace;letter-spacing:.08em}.game-shell{padding-bottom:72px}}
@media(max-width:520px){.top-center{display:none}.sound-button{font-size:8px;padding:7px}.game-layout{padding-top:8px}.stage-topline{height:39px;padding:0 11px}.location b{font-size:8px}.location small{font-size:7px}.stage-bottomline{height:61px;padding:0 9px;gap:7px}.hunter-avatar{width:29px;height:29px;font-size:16px}.hunter-status{gap:6px}.hunter-name{font-size:7px}.hunter-name span{font-size:6px}.consumables{padding-left:7px;gap:4px}.consumable-label{display:none}.weapon-chip{padding-left:7px;gap:5px}.weapon-chip b{font-size:5.5px}.weapon-chip small{font-size:6px}.weapon-icon{font-size:15px}.weapon-chevron{display:none}.control-tip{font-size:6px;padding:6px 7px;bottom:8px}.control-tip i{padding:0 2px}.boss-bar-wrap{top:12px;width:58%}.boss-label{font-size:7px}.boss-label small{font-size:6px;margin-left:5px}.boss-phase{font-size:6px;padding:2px 3px}.progress-row{margin-top:9px}.progress-row>span:first-child,.faint{font-size:6px}.progress-track{max-width:100px}.footer{font-size:6px}.footer span:nth-child(2){display:none}.modal-card{padding:30px 25px 24px}.modal-card h2{font-size:33px}.modal-controls{gap:12px}}

(() => {
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const mapCanvas = document.getElementById('mapCanvas');
  const mapCtx = mapCanvas.getContext('2d');
  const W = 960, H = 600;
  const keys = new Set();
  const pointer = { x: 480, y: 300, down: false, touchStart: null, touchMove: null };
  const ui = {
    start: document.getElementById('startModal'), end: document.getElementById('endModal'), begin: document.getElementById('beginHunt'), restart: document.getElementById('restartHunt'),
    pause: document.getElementById('pauseButton'), health: document.getElementById('healthFill'), healthText: document.getElementById('healthText'), stamina: document.getElementById('staminaFill'),
    boss: document.getElementById('bossFill'), phase: document.getElementById('bossPhase'), behavior: document.getElementById('behaviorText'), potion: document.getElementById('potionCount'),
    clock: document.getElementById('clock'), progress: document.getElementById('progressFill'), percent: document.getElementById('progressPercent'), message: document.getElementById('centerMessage'),
    tip: document.getElementById('controlTip'), sound: document.getElementById('soundToggle')
  };
  let game = { active:false, paused:false, ended:false, won:false, elapsed:0, potions:3, potionUsed:0, messageTime:0, sound:true, last:0, shake:0, particles:[], decals:[], flash:0 };
  const player = { x:480,y:435,vx:0,vy:0,r:14,hp:100,stamina:100,face:-Math.PI/2,attack:0,attackCd:0,attackHit:false,dodge:0,dodgeCd:0,invuln:0,tonic:0,hurt:0 };
  const beast = { x:480,y:213,vx:0,vy:0,r:34,hp:1000,maxHp:1000,state:'stalk',timer:1.6,face:Math.PI/2,hitFlash:0,attackCount:0,phase:1,roar:0 };
  const decor = [];
  let audio;

  function seeded(n){let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)}
  function initDecor(){
    for(let i=0;i<140;i++){let a=seeded(i+4)*Math.PI*2,r=270+seeded(i+80)*260;decor.push({x:480+Math.cos(a)*r,y:300+Math.sin(a)*r,kind:i%5,scale:.55+seeded(i+120)*1.15,rot:seeded(i+180)*6.28,alpha:.35+seeded(i+260)*.45})}
    for(let i=0;i<32;i++)game.decals.push({x:100+seeded(i+420)*760,y:80+seeded(i+510)*440,r:2+seeded(i+600)*9,rot:seeded(i+700)*6.28})
  }
  initDecor();
  function audioTone(freq=240,dur=.08,type='sine',vol=.035){
    if(!game.sound)return;
    try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch(e){}
  }
  function setMessage(text,seconds=1.6){ui.message.textContent=text;ui.message.classList.add('visible');game.messageTime=seconds}
  function begin(){reset();game.active=true;game.paused=false;game.ended=false;ui.start.classList.add('hidden');ui.end.classList.add('hidden');ui.tip.style.display='';setMessage('THE HUNT BEGINS',1.8);audioTone(330,.12,'triangle',.04)}
  function reset(){Object.assign(player,{x:480,y:435,vx:0,vy:0,hp:100,stamina:100,face:-Math.PI/2,attack:0,attackCd:0,attackHit:false,dodge:0,dodgeCd:0,invuln:0,tonic:0,hurt:0});Object.assign(beast,{x:480,y:213,vx:0,vy:0,hp:1000,state:'stalk',timer:1.5,face:Math.PI/2,hitFlash:0,attackCount:0,phase:1,roar:0});Object.assign(game,{elapsed:0,potions:3,potionUsed:0,messageTime:0,shake:0,particles:[],flash:0});ui.potion.textContent='3';ui.clock.textContent='00:00';ui.progress.style.width='0%';ui.percent.textContent='0%';ui.health.style.width='100%';ui.healthText.textContent='100 / 100';ui.stamina.style.width='100%';ui.boss.style.width='100%';ui.behavior.textContent='Stalking';ui.phase.textContent='STALKING';ui.tip.style.display='';}
  function togglePause(){if(!game.active||game.ended)return;game.paused=!game.paused;ui.pause.textContent=game.paused?'▶':'Ⅱ';setMessage(game.paused?'HUNT PAUSED':'',game.paused?99:.01)}
  function end(won){game.ended=true;game.active=false;game.won=won;game.paused=false;document.getElementById('endEyebrow').textContent=won?'THE HUNT IS WON':'THE HUNT IS LOST';document.getElementById('endTitle').innerHTML=won?'A legend<br><em>remembered.</em>':'The wilds<br><em>remain.</em>';document.getElementById('endCopy').textContent=won?'The Gloamwood grows quiet. The Guild will hear of this.':'The forest keeps its secrets. Regroup, hunter, and try again.';document.getElementById('resultTime').textContent=formatTime(game.elapsed);document.getElementById('resultPotions').textContent=game.potionUsed;document.getElementById('resultReward').textContent=won?`${Math.max(180,480-Math.floor(game.elapsed/12)*5)} G`:'—';ui.end.classList.remove('hidden');ui.pause.textContent='Ⅱ';audioTone(won?523:110,.35,'triangle',.05)}
  function formatTime(s){let m=Math.floor(s/60),sec=Math.floor(s%60);return `${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`}
  function getCanvasPoint(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*W/r.width,y:(e.clientY-r.top)*H/r.height}}
  function attack(){if(!game.active||game.paused||game.ended||player.attackCd>0||player.stamina<9)return;player.attack=.36;player.attackCd=.47;player.attackHit=false;player.stamina=Math.max(0,player.stamina-9);audioTone(185,.06,'sawtooth',.018)}
  function dodge(){if(!game.active||game.paused||game.ended||player.dodgeCd>0||player.stamina<24)return;let dx=(keys.has('d')?1:0)-(keys.has('a')?1:0),dy=(keys.has('s')?1:0)-(keys.has('w')?1:0);if(pointer.touchMove){dx=pointer.touchMove.x;dy=pointer.touchMove.y}if(!dx&&!dy){dx=Math.cos(player.face);dy=Math.sin(player.face)}let l=Math.hypot(dx,dy)||1;player.vx=dx/l*410;player.vy=dy/l*410;player.dodge=.24;player.dodgeCd=.8;player.invuln=.48;player.stamina-=24;audioTone(420,.09,'triangle',.03);for(let i=0;i<7;i++)spawnParticle(player.x,player.y,'#c7cead',.6)}
  function heal(){if(!game.active||game.paused||game.ended||game.potions<=0||player.hp>=100)return;game.potions--;game.potionUsed++;player.hp=Math.min(100,player.hp+38);player.tonic=.7;ui.potion.textContent=game.potions;setMessage('VITALITY RESTORED',.8);audioTone(640,.16,'sine',.04)}
  function startAttackFromPointer(){const p=getCanvasPoint({clientX:event.clientX,clientY:event.clientY});pointer.x=p.x;pointer.y=p.y;player.face=Math.atan2(p.y-player.y,p.x-player.x);attack()}
  function spawnParticle(x,y,color,life=.4){game.particles.push({x,y,vx:(Math.random()-.5)*140,vy:(Math.random()-.5)*130,life,max:life,r:2+Math.random()*3,color})}

  function update(dt){
    if(!game.active||game.paused||game.ended)return;
    game.elapsed+=dt;game.shake=Math.max(0,game.shake-dt*18);game.flash=Math.max(0,game.flash-dt*2.7);
    if(game.messageTime>0){game.messageTime-=dt;if(game.messageTime<=0)ui.message.classList.remove('visible')}
