const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox','--disable-dev-shm-usage']});
 const page=await browser.newPage({viewport:{width:1280,height:900},deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push(String(e)));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
 await page.goto('http://localhost:3002',{waitUntil:'networkidle'});
 await page.screenshot({path:'/tmp/opencode/hunt-start.jpg',type:'jpeg',quality:80});
 await page.getByRole('button',{name:/BEGIN THE HUNT/}).click();
 await page.waitForTimeout(1000);
 const start=await page.locator('#clock').innerText();
 await page.keyboard.down('w');await page.waitForTimeout(600);await page.keyboard.up('w');
 await page.mouse.click(640,450);await page.keyboard.press('Space');await page.keyboard.press('q');
 await page.waitForTimeout(900);
 const state=await page.evaluate(()=>({clock:document.querySelector('#clock').textContent,hp:document.querySelector('#healthText').textContent,potions:document.querySelector('#potionCount').textContent,canvas:[document.querySelector('#gameCanvas').width,document.querySelector('#gameCanvas').height],modal:document.querySelector('#startModal').className}));
 await page.screenshot({path:'/tmp/opencode/hunt-playing.jpg',type:'jpeg',quality:80});
 console.log(JSON.stringify({start,state,errors},null,2));await browser.close();
})();

